import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

// Add debug flag
const DEBUG = false;

// Animation item interface
interface AnimationItem {
  id: string;
  type: 'text' | 'list' | 'component';
  priority: number;
  dependencies: string[];
  status: 'pending' | 'active' | 'completed';
  onStart: () => void;
  onComplete: () => void;
}

// Animation context interface
interface AnimationContextType {
  registerAnimation: (
    type: AnimationItem['type'],
    options: {
      priority?: number;
      dependencies?: string[];
      onStart?: () => void;
      onComplete?: () => void;
      name?: string; // Add name for retrieving later
    }
  ) => string;
  completeAnimation: (id: string) => void;
  isAnimating: boolean;
  currentAnimation: AnimationItem | null;
  pauseAll: () => void;
  resumeAll: () => void;
  resetQueue: () => void;
  getAnimationId: (type: string, name?: string) => string;
}

// Create the context with default values
const AnimationContext = createContext<AnimationContextType>({
  registerAnimation: () => '',
  completeAnimation: () => {},
  isAnimating: false,
  currentAnimation: null,
  pauseAll: () => {},
  resumeAll: () => {},
  resetQueue: () => {},
  getAnimationId: () => '',
});

// Custom hook to use the animation context
export const useAnimation = () => useContext(AnimationContext);

// Animation provider props
interface AnimationProviderProps {
  children: ReactNode;
  routeKey?: string; // Used to reset queue on route changes
}

// Generate unique ID for animations
let nextId = 1;
const animationIds: Record<string, string> = {}; // Track IDs by name
const generateId = (type: string, name?: string) => {
  const id = `${type}-${name || nextId++}`;
  if (name) {
    animationIds[name] = id;
  }
  return id;
};

export const AnimationProvider: React.FC<AnimationProviderProps> = ({ 
  children,
  routeKey
}) => {
  // Queue of animations to process
  const [queue, setQueue] = useState<AnimationItem[]>([]);

  // Currently active animation
  const [currentAnimation, setCurrentAnimation] = useState<AnimationItem | null>(null);

  // Paused state
  const [isPaused, setIsPaused] = useState(false);

  // Reset queue when route changes
  useEffect(() => {
    if (routeKey) {
      if (DEBUG) console.log(`Route changed to ${routeKey}, resetting queue`);
      resetQueue();
    }
  }, [routeKey]);

  // Process next animation in queue when current one completes
  useEffect(() => {
    if (isPaused) {
      if (DEBUG) console.log('Animation system is paused');
      return;
    }

    if (currentAnimation) {
      if (DEBUG) console.log(`Current animation is active: ${currentAnimation.id}`);
      return; // Wait for current animation to complete
    }

    // Small delay to avoid React batching issues
    const timer = setTimeout(() => {
      if (queue.length === 0) {
        if (DEBUG) console.log('Queue is empty, nothing to process');
        return;
      }

      // Find pending animations with no dependencies or all dependencies completed
      const eligibleAnimations = queue.filter(item => {
        if (item.status !== 'pending') return false;

        // Check if all dependencies are completed
        const allDependenciesMet = item.dependencies.every(depId => {
          const dependencyItem = queue.find(qItem => qItem.id === depId);
          // If dependency not found, consider it met
          if (!dependencyItem) return true;
          // Otherwise check if it's completed
          return dependencyItem.status === 'completed';
        });

        return allDependenciesMet;
      });

      if (DEBUG && eligibleAnimations.length > 0) {
        console.log(`Found ${eligibleAnimations.length} eligible animations`);
        console.log('Eligible animations:', eligibleAnimations.map(a => a.id));
      }

      // Sort by priority (highest first)
      eligibleAnimations.sort((a, b) => b.priority - a.priority);

      // Select the highest priority animation
      const next = eligibleAnimations[0];

      if (next) {
        if (DEBUG) console.log(`Starting animation: ${next.id} (priority: ${next.priority})`);

        // Update status
        setQueue(prevQueue => 
          prevQueue.map(item => 
            item.id === next.id ? { ...item, status: 'active' } : item
          )
        );

        // Set as current animation
        setCurrentAnimation(next);

        // Start the animation
        next.onStart();
      }
    }, 50); // Small delay to allow React to process state changes

    return () => clearTimeout(timer);
  }, [queue, currentAnimation, isPaused]);

  // Helper to get an animation ID by name
  const getAnimationId = (type: string, name?: string): string => {
    if (name && animationIds[name]) {
      return animationIds[name];
    }
    return '';
  };

  // Register a new animation
  const registerAnimation = (
    type: AnimationItem['type'],
    options: {
      priority?: number;
      dependencies?: string[];
      onStart?: () => void;
      onComplete?: () => void;
      name?: string; // Optional name for retrieving later
    } = {}
  ): string => {
    const id = generateId(type, options.name);

    if (DEBUG) {
      console.log(`Registering animation: ${id}`);
      if (options.dependencies && options.dependencies.length > 0) {
        console.log(`Dependencies: ${options.dependencies.join(', ')}`);
      }
    }

    const newItem: AnimationItem = {
      id,
      type,
      priority: options.priority || 0,
      dependencies: options.dependencies || [],
      status: 'pending',
      onStart: options.onStart || (() => {}),
      onComplete: options.onComplete || (() => {}),
    };

    // Add to queue
    setQueue(prevQueue => [...prevQueue, newItem]);

    return id;
  };

  // Mark an animation as complete
  const completeAnimation = (id: string) => {
    // Only complete if this is the current animation
    if (currentAnimation?.id !== id) {
      if (DEBUG) console.log(`Animation ${id} is not the current animation, ignoring completion`);
      return;
    }

    if (DEBUG) console.log(`Completing animation: ${id}`);

    // Call complete callback
    currentAnimation.onComplete();

    // Update queue
    setQueue(prevQueue => 
      prevQueue.map(item => 
        item.id === id ? { ...item, status: 'completed' } : item
      )
    );

    // Clear current animation
    setCurrentAnimation(null);
  };

  // Pause all animations
  const pauseAll = () => {
    if (DEBUG) console.log('Pausing all animations');
    setIsPaused(true);
  };

  // Resume animations
  const resumeAll = () => {
    if (DEBUG) console.log('Resuming animations');
    setIsPaused(false);
  };

  // Reset the queue
  const resetQueue = () => {
    if (DEBUG) console.log('Resetting animation queue');
    setQueue([]);
    setCurrentAnimation(null);
    setIsPaused(false);
  };

  // Animation context value
  const contextValue: AnimationContextType = {
    registerAnimation,
    completeAnimation,
    isAnimating: !!currentAnimation,
    currentAnimation,
    pauseAll,
    resumeAll,
    resetQueue,
    getAnimationId,
  };

  return (
    <AnimationContext.Provider value={contextValue}>
      {children}
    </AnimationContext.Provider>
  );
};
